// Near/far world footprint agreement for buildings generated by bm_lot_foot.
// The generator's x1/y1 values are the INCLUSIVE last wall tile;
// far boxes accept the EXCLUSIVE outer world edge. Keep one conversion
// in the actual far renderer. No allocations, saved fields or new LOD data.
#ifndef BORE2_HOUSE_FOOTPRINT_H
#define BORE2_HOUSE_FOOTPRINT_H
static inline int house_foot_end_tile(int block, int inclusive_last,
                                       int world_window_tile, int tiles_per_block) {
    return block * tiles_per_block + inclusive_last + 1 - world_window_tile;
}
#endif
